scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsGlideRecord(ast).directFieldAssignments();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-GR-007',
        title: 'Field set by direct assignment',
        recommendation: 'Use setValue(field, value) (or setDisplayValue for display values) instead of assigning to the field property.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
